const { Given, When, Then } = require('@cucumber/cucumber');
const { assert, expect } = require('@cucumber/cucumber').expect || (() => {
  // Minimal assertion helpers. No assertion library dependency.
  const assert = {
    ok(v, msg) { if (!v) throw new Error(msg || 'assertion failed'); },
    equal(a, b, msg) { if (a !== b) throw new Error(msg || `expected ${JSON.stringify(a)} to equal ${JSON.stringify(b)}`); },
    notEqual(a, b, msg) { if (a === b) throw new Error(msg || `expected ${JSON.stringify(a)} to not equal ${JSON.stringify(b)}`); },
  };
  return { assert };
})();

// ---------------------------------------------------------------------------
// Given steps
// ---------------------------------------------------------------------------

// Already handled by the Before hook in world.js; this is a safety check.
Given('the app is loaded', function () {
  if (!this.window || !this.document) throw new Error('app not loaded — the Before hook should have called loadApp()');
});

Given('there are no todos', function () {
  // The Background already ensures no todos; this step is for scenarios that
  // assert the empty state directly. If there ARE todos from a previous step,
  // clear the list.
  const list = this.document.querySelector('ul.todo-list');
  if (list) { list.innerHTML = ''; }
  // Clear localStorage so no stale state leaks across scenarios in the same run.
  this.localStorage.removeItem('todos-vanillajs');
});

Given('I have a todo {string}', function (label) {
  // Create a todo by typing into the new-todo input and pressing Enter.
  const input = this.document.querySelector('input.new-todo');
  input.value = label;
  const event = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true });
  input.dispatchEvent(event);
});

Given('I have todos {string}, {string}, {string}', function (a, b, c) {
  this.document.querySelector('input.new-todo').value = a;
  this.document.querySelector('input.new-todo').dispatchEvent(
    new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true })
  );
  this.document.querySelector('input.new-todo').value = b;
  this.document.querySelector('input.new-todo').dispatchEvent(
    new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true })
  );
  this.document.querySelector('input.new-todo').value = c;
  this.document.querySelector('input.new-todo').dispatchEvent(
    new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true })
  );
});

Given('{string} is completed', function (label) {
  // Find the todo item whose label matches and click its toggle checkbox.
  const items = this.document.querySelectorAll('ul.todo-list li');
  for (const li of items) {
    const labelEl = li.querySelector('label');
    if (labelEl && labelEl.textContent.trim() === label) {
      const toggle = li.querySelector('input.toggle');
      if (toggle && !toggle.checked) {
        toggle.checked = true;
        li.classList.add('completed');
        // Dispatch change event so the app reacts.
        toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
      }
      return;
    }
  }
  throw new Error(`todo "${label}" not found to mark completed`);
});

Given('I have a todo {string} stored in localStorage', function (label) {
