  // Preserve localStorage before disposing the window (happy-dom Window.close()
  // destroys the in-memory storage). The app reads localStorage on init, so it
  // must see the pre-reload state.
  var savedStorage = {};
  if (this.window) {
    var keys = Object.keys(this.localStorage);
    for (var i = 0; i < keys.length; i++) {
      savedStorage[keys[i]] = this.localStorage.getItem(keys[i]);
    }
  }
  this.disposeApp();
  this.loadApp();
  // Restore localStorage after the new Window is created.
  for (var key in savedStorage) {
    if (savedStorage.hasOwnProperty(key)) {
      this.localStorage.setItem(key, savedStorage[key]);
    }
  }
  // Re-trigger app init: reload from localStorage and render.
  // The app's loadTodos/init already ran on DOMContentLoaded; re-run them.
  // Re-dispatch DOMContentLoaded so the app re-initialises from storage.
  this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
});

